int main(void){savepath="build/crowd190.save";eventpath="build/crowd190.csv";audio_init();nextWorldSeed=140;test_reset();g.x=180;g.z=130;for(int i=0;i<NN;i++){PERSON(i).x=189;PERSON(i).z=140;}local_init190();int escaped[LOCAL190]={0},arrived[8]={0},invalid[LOCAL190]={0},jump=0;for(int step=0;step<6500;step++){g.hours=12;realTime+=.1f;float x[LOCAL190],z[LOCAL190],y[LOCAL190];for(int i=0;i<LOCAL190;i++){x[i]=g.locals190[i].x;z[i]=g.locals190[i].z;y[i]=g.locals190[i].y;}traffic_tick140(.1f);local_tick190(.1f);for(int i=0;i<LOCAL190;i++){Local190*c=&g.locals190[i];if(c->stage>=20)escaped[i]=1;if(c->stage==21)arrived[c->role]=1;if(dst(x[i],z[i],c->x,c->z)>.13f||ab(y[i]-c->y)>.3f)jump++;if(step%10==0&&!local_clear190(i,c->x,c->z,c->y)){if(!invalid[i])printf("INVALID %d stage%d step%d %.3f %.3f y%.3f\n",i,c->stage,c->step,c->x,c->z,c->y);invalid[i]=1;}}if(step%1000==0){printf("DAY %d\n",step/10);fflush(stdout);}}
 int out=0,roles=0,bad=0;for(int i=0;i<LOCAL190;i++){out+=escaped[i];bad+=invalid[i];if(!escaped[i])printf("BLOCKED %d stage%d step%d %.2f %.2f y%.2f\n",i,g.locals190[i].stage,g.locals190[i].step,g.locals190[i].x,g.locals190[i].z,g.locals190[i].y);}for(int r=0;r<8;r++){roles+=arrived[r];if(!arrived[r])printf("NO ARRIVAL role%d\n",r);}printf("CROWD190 day: %d/40 exited, %d/8 roles arrived, %d invalid residents, %d teleports\n",out,roles,bad,jump);fflush(stdout);
 for(int step=0;step<7000;step++){g.hours=23;realTime+=.1f;traffic_tick140(.1f);local_tick190(.1f);}int home=0;for(int i=0;i<LOCAL190;i++){Local190*c=&g.locals190[i];if(c->stage==0&&ab(c->y-c->floor*3)<.2f)home++;else printf("NOT HOME %d stage%d step%d pos%.2f %.2f y%.2f\n",i,c->stage,c->step,c->x,c->z,c->y);}printf("CROWD190 night: %d/40 home\n",home);return out==40&&roles==8&&!bad&&!jump&&home==40?0:1;}
